const orderJsonKeys = (jsonObj) => {
  const ordered = {};
  Object.keys(jsonObj).sort().forEach(key => {
    ordered[key] = jsonObj[key];
  });
  return ordered;
}

// Check if file returned with content
if (Object.keys($input.all()[0].json).includes("content")) {
  // Decode base64 content and parse JSON
  const origWorkflow = JSON.parse(Buffer.from($input.all()[0].json.content, 'base64').toString());
  const n8nWorkflow = $input.all()[1].json;

  // Order JSON objects
  const orderedOriginal = orderJsonKeys(origWorkflow);
  const orderedActual = orderJsonKeys(n8nWorkflow);

  // Determine difference
  if (JSON.stringify(orderedOriginal) === JSON.stringify(orderedActual)) {
    $input.all()[0].json.github_status = "same";
  } else {
    $input.all()[0].json.github_status = "different";
    $input.all()[0].json.n8n_data_stringy = JSON.stringify(orderedActual, null, 2);
  }
  $input.all()[0].json.content_decoded = orderedOriginal;
// No file returned / new workflow
} else if (Object.keys($input.all()[0].json).includes("data")) {
  const origWorkflow = JSON.parse($input.all()[0].json.data);
  const n8nWorkflow = $input.all()[1].json;

  // Order JSON objects
  const orderedOriginal = orderJsonKeys(origWorkflow);
  const orderedActual = orderJsonKeys(n8nWorkflow);

  // Determine difference
  if (JSON.stringify(orderedOriginal) === JSON.stringify(orderedActual)) {
    $input.all()[0].json.github_status = "same";
  } else {
    $input.all()[0].json.github_status = "different";
    $input.all()[0].json.n8n_data_stringy = JSON.stringify(orderedActual, null, 2);
  }
  $input.all()[0].json.content_decoded = orderedOriginal;

} else {
  // Order JSON object
  const n8nWorkflow = $input.all()[1].json;
  const orderedActual = orderJsonKeys(n8nWorkflow);

  // Proper formatting
  $input.all()[0].json.github_status = "new";
  $input.all()[0].json.n8n_data_stringy = JSON.stringify(orderedActual, null, 2);
}

// Return items
return $input.all();

const updatedItems = [];

// Loop through every workflow pulled by the n8n node
for (const item of $input.all()) {
  let wf = item.json;

  // Make sure the workflow actually has nodes
  if (wf.nodes && Array.isArray(wf.nodes)) {

    // Iterate through every node inside the current workflow
    wf.nodes.forEach(node => {

      // ==========================================
      // FIX 1: WordPress 'query' to 'search'
      // ==========================================
      if (node.type === 'n8n-nodes-base.httpRequest' && node.parameters?.url?.includes('/wp/v2/media')) {
        let params = node.parameters?.queryParameters?.parameters;

        if (params) {
          // Find the parameter named 'query' and rename it to 'search'
          let queryParam = params.find(p => p.name === 'query');
          if (queryParam) {
            queryParam.name = 'search';
          }
        }
      }

      // ==========================================
      // FIX 2: Gemini Model Prompt Updates
      // ==========================================
      if (node.type === '@n8n/n8n-nodes-langchain.googleGemini') {
        // If you need to programmatically update the prompt text
        // you can access it like this (assuming standard structure):
        /*
        if (node.parameters?.messages?.values?.[0]?.content) {
             let promptContent = node.parameters.messages.values[0].content;
             // Example: node.parameters.messages.values[0].content = promptContent.replace('old text', 'new text');
        }
        */
      }

      // Add additional fixes here as needed

    });
  }

  // Push the updated workflow back into the n8n item stream
  updatedItems.push({ json: wf });
}

// Return the modified workflows to the next node
return updatedItems;

